INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.105.4',
  '2026-09-30',
  'Пульт ТВ: очередь показывается сразу, а не после обновления страницы',
  E'Кнопка «＋ В очередь» добавляла фильм молча: раздел «Очередь» с кнопкой «Смотреть очередь» появлялся только после обновления страницы. Теперь он показывается сразу, и место в списке при этом не теряется — пульт остаётся на той же кнопке.\n\nСама плитка после добавления показывает «✓ В очереди» и не забывает об этом при перерисовке, а кнопки «Смотреть очередь» и «Очистить» переехали к заголовку раздела: раньше они прижимались к правому краю экрана и висели в стороне от всего остального.',
  E'player.html: enqueue() перерисовывает главный экран через новый renderHomeInPlace() — он запоминает scrollTop и активную кнопку по её data-атрибуту (enqueue/open/info) и возвращает фокус после renderHome(); иначе пульт выбрасывало в начало списка. Раньше enqueue() только менял подпись у нажатой кнопки, а раздел «Очередь» рисовался лишь при следующем полном renderHome().\n\nСостояние плитки больше не живёт в подписи кнопки: inQueue(t) проверяет watchList, и плитка рисуется с «✓ В очереди» и классом on. Повторное нажатие говорит осд-подсказкой, а не переписывает кнопку. «✕ Убрать» тоже идёт через renderHomeInPlace.\n\nCSS: у .sec-head h2 убран margin-right:auto (кнопки уезжали к правому краю), добавлен flex-wrap.\n\nПроверено в браузере: раздел появляется на первом же нажатии, фокус и подпись остаются на нажатой кнопке, добавление из карточки «Инфо» видно при возврате на главный экран, «Убрать» и «Очистить» не сбивают место.'
);
-- +goose StatementEnd

